function [a] = dcm(q)
%DCM  The passive ECI -> body matrix of q.
%   q: real[1][4] (passed a plain number)
%   returns a: real[1][3][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = zeros(3, 3);
    x = q(1);
    y = q(2);
    z = q(3);
    w = q(4);
    a = [([(1 - (2 * ((y * y) + (z * z)))); (2 * ((x * y) + (z * w))); (2 * ((x * z) - (y * w)))]).'; ([(2 * ((y * x) - (z * w))); (1 - (2 * ((x * x) + (z * z)))); (2 * ((y * z) + (x * w)))]).'; ([(2 * ((z * x) + (y * w))); (2 * ((z * y) - (x * w))); (1 - (2 * ((x * x) + (y * y))))]).'];
end
